variables.input:
timeseries n = count(zeebe.health), by: {k8s.namespace.name}
| fields k8s.namespace.name
| sort k8s.namespace.name asc

5.query:
timeseries memory_used = sum(jvm.buffer.memory.used),
  by: {k8s.namespace.name, k8s.pod.name, id},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

6.query:
timeseries memory_used = sum(netty.allocator.memory.used, filter:{allocator_type == "PooledByteBufAllocator"}),
  by: {k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

7.query:
timeseries memory_used = sum(netty.allocator.memory.used, filter:{allocator_type == "UnpooledByteBufAllocator"}),
  by: {k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

9.query:
timeseries gc_seconds_per_sec = sum(jvm.gc.pause, rate:1s),
  by: {k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

11.query:
timeseries cpu_throttled = avg(dt.kubernetes.container.cpu_throttled),
  by: {k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

12.query:
timeseries cpu_usage = sum(dt.kubernetes.container.cpu_usage),
  by: {k8s.pod.name, k8s.container.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

17.query:
timeseries persistentvolumeclaim_available = avg(dt.kubernetes.persistentvolumeclaim.available),
  by: {k8s.persistentvolumeclaim.name, k8s.namespace.name},
  filter: {in(k8s.namespace.name, array($Namespace))}

23.query:
timeseries memory_size = avg(zeebe.elasticsearch.exporter.bulk.memory.size),
  by: {k8s.pod.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

30.query:
timeseries actor_task_execution_count_per_sec = sum(zeebe.actor_task_execution_count, rate:1s),
  by: {actorName},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

31.query:
timeseries queue_length = sum(zeebe.actor.task.queue.length),
  by: {actorName},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

33.query:
timeseries activated_per_sec = sum(zeebe.client.worker.job.activated, rate:1s),
  by: {k8s.namespace.name, workerName, jobType},
  filter: {in(k8s.namespace.name, array($Namespace))}

34.query:
timeseries handled_per_sec = sum(zeebe.client.worker.job.handled, rate:1s),
  by: {k8s.namespace.name, workerName, jobType},
  filter: {in(k8s.namespace.name, array($Namespace))}

39.query:
timeseries try_count_per_sec = sum(zeebe.broker.jobs.fail.try.count, rate:1s),
  by: {k8s.pod.name, code},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

40.query:
timeseries try_per_sec = sum(zeebe.gateway.job.stream.push.fail.try, rate:1s),
  by: {k8s.pod.name, code},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

41.query:
timeseries job_events_per_sec = sum(zeebe.job.events.total, rate:1s, filter:{action == "pushed"}),
  by: {k8s.namespace.name, partition},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod)) and in(partition, array($Partition))}

43.query:
timeseries clients = sum(zeebe.gateway.job.stream.clients),
  by: {k8s.namespace.name, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

44.query:
timeseries streams = sum(zeebe.gateway.job.stream.streams),
  by: {k8s.namespace.name, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

45.query:
timeseries stream_count = sum(zeebe.broker.open.job.stream.count),
  by: {k8s.namespace.name, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}

46.query:
timeseries servers = sum(zeebe.gateway.job.stream.servers),
  by: {k8s.namespace.name, k8s.pod.name},
  filter: {in(k8s.namespace.name, array($Namespace)) and in(k8s.pod.name, array($Pod))}
